// ─── Load Market Data from JSON ─────────────────────────────────────────────

async function loadMarketData() {
    try {
        const resp = await fetch('data/market-data.json');
        if (!resp.ok) throw new Error(`HTTP ${resp.status}`);
        marketData = await resp.json();

        // Populate liveSpots from loaded data
        if (marketData.spots) {
            for (const [name, price] of Object.entries(marketData.spots)) {
                if (price != null && price > 0) {
                    liveSpots[name] = price;
                }
            }
        }

        // Fallback: use front-month futures price when spot is missing
        if (marketData.termStructures) {
            for (const [name, ts] of Object.entries(marketData.termStructures)) {
                if (liveSpots[name] == null && ts.prices && ts.prices.length > 0) {
                    liveSpots[name] = ts.prices[0];
                    console.log(`[Market Data] Using front-month as spot for ${name}: ${ts.prices[0]}`);
                }
            }
        }

        console.log(`[Market Data] Loaded — updated ${marketData.updated}`);
        return marketData;
    } catch (e) {
        console.error('[Market Data] Failed to load market-data.json:', e.message);
        return null;
    }
}

// ─── Data Access Functions ──────────────────────────────────────────────────

function getTermStructureAtDate(commodity, dateStr) {
    const contracts = marketData?.contractHistory?.[commodity];
    if (!contracts || !contracts.length) return null;

    const cfg = ENERGY_COMMODITIES[commodity];
    const months = [];
    const prices = [];

    for (const c of contracts) {
        if (!c.dates || !c.dates.length || !c.close) continue;

        let price = null;
        const idx = c.dates.findIndex(d => d >= dateStr);

        if (idx === -1) {
            // All dates are before target — use last available
            price = c.close[c.close.length - 1];
        } else if (c.dates[idx] === dateStr) {
            // Exact match
            price = c.close[idx];
        } else if (idx > 0) {
            // Use the nearest date before target
            price = c.close[idx - 1];
        } else {
            // idx === 0, target is before all data — use first available
            price = c.close[0];
        }

        if (price != null && price > 0) {
            months.push(c.label);
            prices.push(price);
        }
    }

    if (months.length < 3) return null;
    return { months, prices, unit: cfg?.unit, date: dateStr };
}

function getTermStructure(commodity) {
    if (!marketData?.termStructures?.[commodity]) return null;
    const ts = marketData.termStructures[commodity];
    return {
        months: ts.months,
        prices: ts.prices,
        unit: ts.unit,
        spot: liveSpots[commodity] || ts.prices[0],
    };
}

function getTimespreadHistory(spreadName) {
    if (!marketData?.timespreads?.[spreadName]) return null;
    const ts = marketData.timespreads[spreadName];
    return {
        dates: ts.dates,
        values: ts.values,
        name: spreadName,
        unit: ts.unit,
    };
}

function getSpreadHistory(spreadKey, nDays) {
    const def = SPREAD_DEFINITIONS[spreadKey];
    if (!def || !marketData?.history) return null;

    if (def.formula === 'custom' && spreadKey === '3-2-1 Crack Spread') {
        return _computeCrackHistory(nDays, 2, 1, 3, '3-2-1 Crack Spread');
    }
    if (def.formula === 'custom' && spreadKey === '2-1-1 Crack Spread') {
        return _computeCrackHistory(nDays, 1, 1, 2, '2-1-1 Crack Spread');
    }

    if (def.formula === 'fwd') return null;

    const longCfg = ENERGY_COMMODITIES[def.long];
    const shortCfg = ENERGY_COMMODITIES[def.short];
    if (!longCfg || !shortCfg) return null;

    const longHist = marketData.history[longCfg.continuous];
    const shortHist = marketData.history[shortCfg.continuous];
    if (!longHist || !shortHist) return null;

    const shortMap = {};
    shortHist.dates.forEach((d, i) => shortMap[d] = shortHist.close[i]);

    const dates = [];
    const values = [];
    for (let i = 0; i < longHist.dates.length; i++) {
        const d = longHist.dates[i];
        if (shortMap[d] != null) {
            dates.push(d);
            values.push(+(longHist.close[i] * def.ratio.long - shortMap[d] * def.ratio.short).toFixed(2));
        }
    }

    // Trim to nDays
    const trimmed = _trimToDays(dates, values, nDays);
    if (trimmed.dates.length < 10) return null;

    const current = trimmed.values[trimmed.values.length - 1];
    return { dates: trimmed.dates, values: trimmed.values, name: spreadKey, unit: def.unit, current };
}

function _computeCrackHistory(nDays, rbCoeff, hoCoeff, clCoeff, label) {
    if (!marketData?.history) return null;
    const rbHist = marketData.history['RB=F'];
    const hoHist = marketData.history['HO=F'];
    const clHist = marketData.history['CL=F'];
    if (!rbHist || !hoHist || !clHist) return null;

    const hoMap = {};
    hoHist.dates.forEach((d, i) => hoMap[d] = hoHist.close[i]);
    const clMap = {};
    clHist.dates.forEach((d, i) => clMap[d] = clHist.close[i]);

    const dates = [];
    const values = [];
    for (let i = 0; i < rbHist.dates.length; i++) {
        const d = rbHist.dates[i];
        if (hoMap[d] != null && clMap[d] != null) {
            dates.push(d);
            values.push(+((rbCoeff * rbHist.close[i] * 42 + hoCoeff * hoMap[d] * 42 - clCoeff * clMap[d]) / clCoeff).toFixed(2));
        }
    }

    const trimmed = _trimToDays(dates, values, nDays);
    if (trimmed.dates.length < 10) return null;

    const current = trimmed.values[trimmed.values.length - 1];
    return { dates: trimmed.dates, values: trimmed.values, name: label, unit: '$/bbl', current };
}

function _trimToDays(dates, values, nDays) {
    if (!nDays || dates.length <= nDays) return { dates, values };
    const start = dates.length - nDays;
    return { dates: dates.slice(start), values: values.slice(start) };
}

function computeSpreadValue(spreadKey) {
    const def = SPREAD_DEFINITIONS[spreadKey];
    if (!def) return null;

    if (def.formula === 'custom') {
        const rb = liveSpots['RBOB Gasoline (RB)'];
        const ho = liveSpots['Heating Oil (HO)'];
        const cl = liveSpots['WTI Crude Oil (CL)'];
        if (rb == null || ho == null || cl == null) return null;

        if (spreadKey === '3-2-1 Crack Spread') {
            return +((2 * rb * 42 + ho * 42 - 3 * cl) / 3).toFixed(2);
        }
        if (spreadKey === '2-1-1 Crack Spread') {
            return +((rb * 42 + ho * 42 - 2 * cl) / 2).toFixed(2);
        }
        return null;
    }

    if (def.formula === 'fwd') return null;

    const longPrice = liveSpots[def.long];
    const shortPrice = liveSpots[def.short];
    if (longPrice == null || shortPrice == null) return null;
    return +((longPrice * def.ratio.long - shortPrice * def.ratio.short)).toFixed(2);
}

function getDataTimestamp() {
    if (!marketData?.updated) return null;
    return new Date(marketData.updated);
}
